function ledger(list){const by=new Map((data?.ledger||[]).map(l=>[String(l.code),l]));return list.map(i=>by.get(String(i.code))||{code:i.code,stage:i.stage,decision:i.decision,confirmation:i.finance_status,annual_potential:i.annual_effect,ebitda_2027:null,cash_2027:i.net_2027,hours:i.total_hours});}
