function strictComparablePrevious(){if(!previousUnique()||data.snapshotMethod&&data.snapshotMethod!=='Портфель 2027 / v6')return false;const rows=(data.previousSnapshot||[]).filter(r=>r.code),confirmed=rows.filter(approved);if(confirmed.some(r=>Number(r.year)!==2027||r.method!=='Портфель 2027 / v6'||![r.annual_potential,r.ebitda_2027,r.cash_2027].every(number)||!['Конечный эффект','Поддерживающий вклад'].includes(r.effect_role)))return false;for(const r of confirmed){if(r.effect_role==='Поддерживающий вклад'&&(r.annual_potential!==0||r.ebitda_2027>0||r.cash_2027>0))return false;if(r.effect_role==='Конечный эффект'){const group=String(r.effect_group||'');if(group.length<3)return false;const members=rows.filter(x=>String(x.effect_group||'')===group);if(members.some(x=>!approved(x))||members.filter(x=>x.effect_role==='Конечный эффект').length!==1)return false;}}return true;}
function canonicalDelta(list,stage,key){if(data.dirty||data.cacheReady===false||list.length!==data.initiatives.length)return null;const row=(data.tracker||[]).find(r=>stageCode(r)===stage);const v=row?.[key];return typeof v==='string'||number(v)?v:null;}
function deltaCount(list,stage){if(initial())return'Исходный срез';if(!previousUnique())return'Требуется сопоставимый срез';const canonical=canonicalDelta(list,stage,'count_delta');if(canonical!==null)return number(canonical)?(canonical>0?'+':'')+canonical:canonical;const ids=new Set(list.map(i=>String(i.code)));const before=(data.previousSnapshot||[]).filter(p=>ids.has(String(p.code))&&stageCode(p)===stage).length,now=list.filter(i=>stageCode(i)===stage).length;return (now-before>0?'+':'')+(now-before);}
function deltaMoney(list,stage){if(initial())return'Исходный срез';if(data.dirty||data.cacheReady===false)return recalculate();if(!strictComparablePrevious())return'Требуется сопоставимый срез';const canonical=canonicalDelta(list,stage,'ebitda_delta');if(canonical!==null)return number(canonical)?fmt(canonical)+' млн руб':canonical;const ids=new Set(list.map(i=>String(i.code))),current=ledger(list.filter(i=>stageCode(i)===stage)).filter(l=>approved(l)&&number(l.ebitda_2027)),prior=(data.previousSnapshot||[]).filter(l=>ids.has(String(l.code))&&stageCode(l)===stage&&approved(l)&&number(l.ebitda_2027));if(!current.length||!prior.length)return'Требуется сопоставимый расчёт';return fmt(current.reduce((n,l)=>n+l.ebitda_2027,0)-prior.reduce((n,l)=>n+l.ebitda_2027,0))+' млн руб';}
