function renderOverview(list){const pending=list.filter(i=>stageCode(i)==='Уточнить').length;$('#overview').innerHTML='<div class="overview-grid"><aside class="panel stage-panel"><h2>Команда уточняет стадии</h2><p class="caption">Комитет распределяет инициативы</p><div class="pending"><strong>'+pending+'</strong><span>Стадия «Уточнить»</span><br><small>Изменение: '+esc(deltaCount(list,'Уточнить'))+'</small></div>'+stages.map(([c,t])=>'<div class="stage-row"><b>'+c+'</b><span>'+t+'</span><span class="numeric">'+list.filter(i=>stageCode(i)===c).length+'</span></div>').join('')+'<button class="plain" data-action="view" data-view="tracker">Открыть трекер стадий</button></aside><div class="panel"><h2>Инициативы связываются с переделами</h2><p class="caption">Участок открывает связанные проекты, код ведёт к паспорту</p><div class="map-wrap">'+mapSvg(list)+'</div><div class="map-caption"><span>Команда проверяет расположение участков<br>Связи кодов берутся из поля «Площадка / передел»</span><button class="plain" data-action="view" data-view="map">Развернуть карту</button></div></div></div><section class="timeline-preview"><div class="view-title"><div><h2>Сроки стадий связывают решения и инициативы</h2><p class="caption">Директор ИТ → куратор → сотрудник → инициатива → пять сроков стадий</p></div><button class="plain" data-action="view" data-view="gantt">Открыть сроки стадий</button></div>'+previewCalendar(list)+'</section><section class="section-block"><h2>Коды ведут к следующему действию</h2>'+projectTable(list.slice(0,8))+'</section>';}
function renderTracker(list){$('#tracker').innerHTML=heading('Трекер связывает стадии, эффекты и изменения','Статус расчёта отделяет подтверждённые эффекты от оценок для согласования', '<button data-action="print" data-kind="tracker">Печать / PDF</button>')+'<div class="notice">Стадия «Уточнить»: '+list.filter(i=>stageCode(i)==='Уточнить').length+' инициатив / '+'изменение: '+esc(deltaCount(list,'Уточнить'))+'</div><div class="table-wrap"><table><thead><tr><th>Стадия</th><th class="numeric">Количество</th><th>Изменение</th><th>Подтверждённая EBITDA 2027</th><th>Оценка EBITDA 2027</th><th>Изменение EBITDA</th><th>Коды</th></tr></thead><tbody>'+stages.map(([c,t])=>{const items=list.filter(i=>stageCode(i)===c),cf=finance(items,'ebitda_2027',true),hf=finance(items,'ebitda_2027',false);return '<tr><td>'+c+' / '+t+'</td><td class="numeric">'+items.length+'</td><td>'+deltaCount(list,c)+'</td><td>'+money(cf)+'<br><small>Оценок: '+cf.count+'</small></td><td>'+money(hf)+'<br><small>Оценок: '+hf.count+'</small></td><td>'+deltaMoney(list,c)+'</td><td>'+items.map(codeButton).join(' ')+'</td></tr>';}).join('')+'</tbody></table></div><section class="section-block"><h2>Портфель готовится к решению комитета</h2>'+projectTable(list)+'</section>';}
